repo.parcels.py:
"""Parcel records."""


class Parcel:
    def __init__(self, depot, grams):
        self.depot = depot
        self.grams = grams

    def __repr__(self):
        return "Parcel(%r, %r)" % (self.depot, self.grams)


ROWS = [('york', 47), ('leeds', 23), ('york', 30), ('hull', 31), ('leeds', 10), ('bath', 59)]


def load_parcels():
    """Yield the stored parcels one at a time."""
    for depot, grams in ROWS:
        yield Parcel(depot, grams)

