"""Share of the total grams per parcel."""
from parcels import load_parcels


def grams_shares(parcels):
    """Return each parcel's share of the total grams, in order."""
    total = sum(x.grams for x in parcels)
    return [x.grams / total for x in parcels]


def stored_shares():
    """Shares for the stored parcels."""
    return grams_shares(load_parcels())


def top_share(parcels):
    """Return the largest share, or 0.0 when there are no parcels."""
    shares = grams_shares(parcels)
    return max(shares) if shares else 0.0


def largest_grams(parcels):
    """Return the largest grams, or None when there are no parcels."""
    values = [x.grams for x in parcels]
    return max(values) if values else None


def describe_parcel(parcel):
    """Return a one-line description of a parcel."""
    return "%s: %s" % (parcel.depot, parcel.grams)

